rmw_qos_profile_t proc_control::pr_ROS2PubSubBase_setQOSProfile
  (rmw_qos_profile_t rmwProfile, real_T qosDepth, real_T qosDeadline, real_T
   qosLifespan, real_T qosLeaseDuration, boolean_T
   qosAvoidROSNamespaceConventions)
{
  sJ4ih70VmKcvCeguWN0mNVF liveliness_lease_duration;
  real_T input;
  real_T sec;
  input = qosDeadline;

  // Start for MATLABSystem: '<S16>/SinkBlock' incorporates:
  //   MATLABSystem: '<S133>/SinkBlock'

  if (qosDeadline == (rtInf)) {
    input = 0.0;
  }

  sec = std::floor(input);
  proc_control_B.deadline_jk.sec = sec;

  // Start for MATLABSystem: '<S16>/SinkBlock' incorporates:
  //   MATLABSystem: '<S133>/SinkBlock'

  proc_control_B.deadline_jk.nsec = (input - sec) * 1.0E+9;
  input = qosLifespan;

  // Start for MATLABSystem: '<S16>/SinkBlock' incorporates:
  //   MATLABSystem: '<S133>/SinkBlock'

  if (qosLifespan == (rtInf)) {
    input = 0.0;
  }

  sec = std::floor(input);
  proc_control_B.lifespan.sec = sec;

  // Start for MATLABSystem: '<S16>/SinkBlock' incorporates:
  //   MATLABSystem: '<S133>/SinkBlock'

  proc_control_B.lifespan.nsec = (input - sec) * 1.0E+9;
  input = qosLeaseDuration;

  // Start for MATLABSystem: '<S16>/SinkBlock' incorporates:
  //   MATLABSystem: '<S133>/SinkBlock'

  if (qosLeaseDuration == (rtInf)) {
    input = 0.0;
  }

  sec = std::floor(input);
  liveliness_lease_duration.sec = sec;

  // Start for MATLABSystem: '<S16>/SinkBlock' incorporates:
  //   MATLABSystem: '<S133>/SinkBlock'

  liveliness_lease_duration.nsec = (input - sec) * 1.0E+9;
  SET_QOS_VALUES(rmwProfile, RMW_QOS_POLICY_HISTORY_KEEP_LAST,
                 static_cast<size_t>(qosDepth),
                 RMW_QOS_POLICY_DURABILITY_VOLATILE,
                 RMW_QOS_POLICY_RELIABILITY_RELIABLE, proc_control_B.deadline_jk,
                 proc_control_B.lifespan, RMW_QOS_POLICY_LIVELINESS_AUTOMATIC,
                 liveliness_lease_duration, (bool)
                 qosAvoidROSNamespaceConventions);
  return rmwProfile;
}

