void proc_control::proc_cont_PolyTrajSys_setupImpl
  (robotics_slcore_internal_bl_p_T *obj)
{
  int32_T b_j;
  for (b_j = 0; b_j < 6; b_j++) {
    // Start for MATLABSystem: '<S337>/Polynomial Trajectory'
    obj->PrevOptInputs.f1[b_j] = 1.0;
  }

  // Start for MATLABSystem: '<S337>/Polynomial Trajectory'
  obj->PrevOptInputs.f2[0] = 1.0;
  obj->PrevOptInputs.f2[1] = 1.0;
  proc_control_B.dv29[0] = 1.0;
  proc_control_B.dv29[1] = 1.0;
  for (b_j = 0; b_j < 3; b_j++) {
    // Start for MATLABSystem: '<S337>/Polynomial Trajectory'
    proc_control_B.obj[0] = obj->VelocityBoundaryCondition[b_j];
    proc_control_B.obj[1] = obj->VelocityBoundaryCondition[b_j + 3];
    proc_contro_generateCubicCoeffs(proc_control_B.dv29, proc_control_B.obj, 1.0,
      proc_control_B.modBreaks);
    proc_control_B.coefMat_j[b_j] = proc_control_B.modBreaks[0];
    proc_control_B.coefMat_j[b_j + 3] = proc_control_B.modBreaks[1];
    proc_control_B.coefMat_j[b_j + 6] = proc_control_B.modBreaks[2];
    proc_control_B.coefMat_j[b_j + 9] = proc_control_B.modBreaks[3];
  }

  proc_control_B.dv29[0] = 1.0;
  proc_control_B.dv29[1] = 2.0;
  pr_addFlatSegmentsToPPFormParts(proc_control_B.dv29, proc_control_B.coefMat_j,
    proc_control_B.modBreaks, proc_control_B.modCoeffs_k);

  // Start for MATLABSystem: '<S337>/Polynomial Trajectory'
  PolyTrajSys_updateStoredPPForms(obj, proc_control_B.modBreaks,
    proc_control_B.modCoeffs_k);
  obj->PPFormUpdatedNeeded = false;
}

